import { SceneComposer } from "retiam";

const composer = new SceneComposer();
await composer.init(canvas);
composer.add(worldScene, { zIndex: 0 });
composer.add(overlayScene, { zIndex: 10 });
composer.start();
await Promise.all([worldScene.run(), overlayScene.run()]);
// Later, when disposing the host:
composer.destroy();
